 public static int Run(){int n=0;foreach(string kind in new[]{"OWNER","USE","OCCUPANT","IDENTITY"})foreach(bool result in new[]{false,true})foreach(bool enabled in new[]{false,true})foreach(string callback in new[]{"none","replaceFrame","clearArgs"}){
 AICF_QuotaCensusDecisionProbe.Stop();Shim.Logs.Clear();var service=new AICF_AIWorldQuotaService();var owner=new AICF_AIQuotaVehicleOwner{m_Service=service,Result=result};var use=new AICF_AIQuotaVehicleUse{Result=result};var occupant=new AICF_AIQuotaVehicleOccupant{Result=result};var identity=new AICF_AIQuotaVehicleEntity{Result=result};NativeBase target=owner;if(kind=="USE")target=use;else if(kind=="OCCUPANT")target=occupant;else if(kind=="IDENTITY")target=identity;AICF_QuotaCensusDecisionFrame successor=null;if(enabled)AICF_QuotaCensusDecisionProbe.Begin(service,service.m_World,"INSTANCE","");if(enabled&&callback=="replaceFrame")target.During=()=>{successor=AICF_QuotaCensusDecisionProbe.Begin(service,service.m_World,"SUCCESSOR","");};if(callback=="clearArgs")target.During=()=>{owner.m_Identity=null;use.m_Identity=null;occupant.m_Entity=null;identity.m_Entity=null;};bool actual=false;switch(kind){case"OWNER":actual=owner.IsCurrent();break;case"USE":actual=use.IsCurrent();break;case"OCCUPANT":actual=occupant.IsCurrent();break;case"IDENTITY":actual=identity.IsCurrent();break;}if(actual!=result||target.Calls!=1||target.Writes!=0||target.Args.Length!=0)throw new Exception(kind+" instance transparency");if(!enabled&&Shim.Logs.Count!=0)throw new Exception("disabled instance observed");if(result&&Shim.Logs.Count!=0)throw new Exception("positive instance observed");if(enabled&&callback=="replaceFrame"&&AICF_QuotaCensusDecisionProbe.s_Frame!=successor)throw new Exception("instance erased successor");n++;}return n;}
 public static int Hierarchy(){int n=0;AICF_QuotaCensusDecisionProbe.Stop();Shim.Logs.Clear();var world=new BaseWorld();var root=new IEntity{Id=101,World=world};world.Entities[root.Id]=root;var character=new ChimeraCharacter{Id=102,World=world,Parent=root};root.FirstChild=character;var item=new IEntity{Id=103,World=world,Parent=character,Inventory=true,Manager=true};character.FirstChild=item;string text=AICF_QuotaCensusDecisionProbe.HierarchyAfter(root);if(!text.Contains("hierarchy_nodes=3")||!text.Contains("hierarchy_character_subtree_nodes=2")||!text.Contains("hierarchy_inventory_items=1")||!text.Contains("hierarchy_managers=1")||!text.Contains("hierarchy_walk_complete=True")||!text.Contains("AFTER_DECISION_NOT_ORIGINAL_INPUT"))throw new Exception("character subtree witness");n++;
 int reads=root.ChildrenReads;if(AICF_QuotaCensusDecisionProbe.HierarchyAfter(root)!=""||root.ChildrenReads!=reads)throw new Exception("duplicate failure walked hierarchy before1s");n++;Clock.Now+=999;if(AICF_QuotaCensusDecisionProbe.HierarchyAfter(root)!="")throw new Exception("early hierarchy cadence");Clock.Now++;string repeated=AICF_QuotaCensusDecisionProbe.HierarchyAfter(root);if(repeated!=text)throw new Exception("value-only stable signature changed");n++;
 var service=new AICF_AIWorldQuotaService();var frame=AICF_QuotaCensusDecisionProbe.Begin(service,service.m_World,"HIERARCHY","");if(!AICF_QuotaCensusDecisionProbe.Want(frame,"HIERARCHY_AFTER",text)||AICF_QuotaCensusDecisionProbe.Want(frame,"HIERARCHY_AFTER",repeated))throw new Exception("unchanged hierarchy signature repeated");Clock.Now+=1000;item.Sibling=new IEntity{Id=104,World=world,Parent=character};string changed=AICF_QuotaCensusDecisionProbe.HierarchyAfter(root);if(changed==text||!AICF_QuotaCensusDecisionProbe.Want(frame,"HIERARCHY_AFTER",changed))throw new Exception("changed hierarchy hidden by dedupe");n++;
 foreach(int count in new[]{256,300,512,513}){AICF_QuotaCensusDecisionProbe.Stop();root=new IEntity{Id=count,World=world};world.Entities[root.Id]=root;IEntity previous=null;for(int i=1;i<count;i++){var child=new IEntity{Id=count*1000+i,World=world,Parent=root};if(previous==null)root.FirstChild=child;else previous.Sibling=child;previous=child;}text=AICF_QuotaCensusDecisionProbe.HierarchyAfter(root);if(count<=512){if(!text.Contains("hierarchy_nodes="+count+" ")||!text.Contains("hierarchy_walk_complete=True"))throw new Exception("bounded complete hierarchy"+count);}else if(!text.Contains("hierarchy_nodes=512 ")||!text.Contains("hierarchy_truncated=True")||!text.Contains("hierarchy_walk_complete=False"))throw new Exception("unexamined suffix claimed complete");n++;}
 foreach(string edge in new[]{"cycle","parent","world","rootChanged"}){AICF_QuotaCensusDecisionProbe.Stop();root=new IEntity{Id=201,World=world};world.Entities[root.Id]=root;item=new IEntity{Id=202,World=world,Parent=root};root.FirstChild=item;if(edge=="cycle")item.Sibling=root;if(edge=="parent")item.Parent=new IEntity();if(edge=="world")item.World=new BaseWorld();if(edge=="rootChanged")root.OnChildren=()=>root.Id++;text=AICF_QuotaCensusDecisionProbe.HierarchyAfter(root);if(edge=="cycle"&&!text.Contains("hierarchy_duplicate_edges=1"))throw new Exception(edge);if(edge=="parent"&&!text.Contains("hierarchy_parent_mismatch=1"))throw new Exception(edge);if(edge=="world"&&!text.Contains("hierarchy_foreign_world=1"))throw new Exception(edge);if(edge=="rootChanged"&&!text.Contains("hierarchy_root_stable=False"))throw new Exception(edge);if(edge!="rootChanged"&&!text.Contains("hierarchy_walk_complete=False"))throw new Exception("bad hierarchy claimed complete");n++;}
 AICF_QuotaCensusDecisionProbe.Stop();for(int i=0;i<AICF_QuotaCensusDecisionProbe.MAX_HIERARCHY_CARS;i++)if(!AICF_QuotaCensusDecisionProbe.HierarchyDue("CAR"+i))throw new Exception("cache early bound");if(AICF_QuotaCensusDecisionProbe.HierarchyDue("OVER")||!AICF_QuotaCensusDecisionProbe.s_bHierarchyOverflow)throw new Exception("hierarchy cache overflow hidden");n++;
 AICF_QuotaCensusDecisionProbe.Stop();if(AICF_QuotaCensusDecisionProbe.s_HierarchyKeys.Count!=0||AICF_QuotaCensusDecisionProbe.s_HierarchyAt.Count!=0||AICF_QuotaCensusDecisionProbe.s_bHierarchyOverflow)throw new Exception("hierarchy Stop retains state");n++;
 AICF_QuotaCensusDecisionProbe.Stop();var snapshot=new AICF_AIQuotaCensus{Result=false};frame=AICF_QuotaCensusDecisionProbe.Begin(service,snapshot.m_World,"QUARTETS","");snapshot.m_aRows.Add(new AICF_AIQuotaAgentRow{m_EntityId=1,m_bCounted=false,m_bActivated=false});snapshot.m_aRows.Add(new AICF_AIQuotaAgentRow{m_EntityId=2,m_bCounted=false,m_bActivated=true});snapshot.m_aRows.Add(new AICF_AIQuotaAgentRow{m_EntityId=3,m_bCounted=true,m_bActivated=false});snapshot.m_aRows.Add(new AICF_AIQuotaAgentRow{m_EntityId=4,m_bCounted=true,m_bActivated=true,m_bVehicle=true});Shim.Logs.Clear();snapshot.Capture(snapshot.m_World);text=string.Join("\n",Shim.Logs);foreach(string expected in new[]{"cached_q00=1","cached_q01=1","cached_q10=1","cached_q11=1","cached_total_counted=2","cached_vehicles=1","cached_vehicle_q11=1","STORED_NOT_ORIGINAL_LOCALS"})if(!text.Contains(expected))throw new Exception("cached histogram "+expected);int logs=Shim.Logs.Count;snapshot.Capture(snapshot.m_World);if(Shim.Logs.Count!=logs)throw new Exception("same cached signature repeated");snapshot.m_aRows[2].m_bActivated=true;snapshot.Capture(snapshot.m_World);if(Shim.Logs.Count<=logs)throw new Exception("changed quartet hidden under same reason/context");n++;
 AICF_QuotaCensusDecisionProbe.Stop();frame=AICF_QuotaCensusDecisionProbe.Begin(service,service.m_World,"MAIN_WORLD","");if(AICF_QuotaCensusDecisionProbe.ForEntityWorld(new BaseWorld())!=null)throw new Exception("foreign BaseWorld accepted");n++;return n;}
 }
